export const title = "Conventional Commits — پیام به‌عنوان API";
export const label = "فصل ۲۲ · Conventional Commits";
export const part = 1;
export const html = "<p class=\"lead\">Conventional Commits یعنی پیام را با قالب ثابت بنویسی: <code>نوع(محدوده): خلاصه</code>. مثال: <code>feat(auth): add refresh token</code>. ابزارها از روی نوع می‌فهمند نسخه و changelog را چطور عوض کنند.</p>\n  <h2><span class=\"hx\"><span class=\"hx-t\">🎯 اهداف یادگیری</span></span></h2>\n<ul>\n<li>مشخصات Conventional Commits 1.0.0 را رعایت کنی</li>\n<li><code>feat!</code> و BREAKING CHANGE را درست علامت بزنی</li>\n<li>commitlint را در ذهن داشته باشی (پیاده در فصل ۲۵)</li>\n<li>در VS Code پیام را بدون درد بنویسی</li>\n</ul>\n<h2><span class=\"hx\"><span class=\"hx-t\">📜 مشخصات</span></span></h2>\n<div class=\"code\"><div class=\"code-head\"><span class=\"dots\"><i></i><i></i><i></i></span><span class=\"fname\">فرمول</span></div><pre>type(scope)!: description\n\n[body]\n\n[footer]\n</pre></div>\n<p class=\"keep-next\">انواع استاندارد: <code>feat</code>، <code>fix</code>، <code>docs</code>، <code>style</code>، <code>refactor</code>، <code>perf</code>، <code>test</code>، <code>build</code>، <code>ci</code>، <code>chore</code>، <code>revert</code>.</p>\n<div class=\"code\"><div class=\"code-head\"><span class=\"dots\"><i></i><i></i><i></i></span><span class=\"fname\">نمونه‌ها</span></div><pre>feat(auth): add rotating refresh tokens\nfix(pdf): embed Vazirmatn to avoid tofu glyphs\ndocs(readme): add PDF badge\nfeat(api)!: drop v1 endpoints\n\nBREAKING CHANGE: clients must use /v2\n</pre></div>\n<p class=\"keep-next\">Semantic Release:</p>\n<ul>\n<li><code>fix</code> → PATCH (1.2.3 → 1.2.4)</li>\n<li><code>feat</code> → MINOR (1.2.3 → 1.3.0)</li>\n<li><code>!</code> یا BREAKING CHANGE → MAJOR (1.2.3 → 2.0.0)</li>\n</ul>\n<h2><span class=\"hx\"><span class=\"hx-t\">✍️ در VS Code</span></span></h2>\n<p class=\"keep-next\">افزونهٔ <em>Conventional Commits</em> فرم می‌دهد. یاSnippet:</p>\n<div class=\"code\"><div class=\"code-head\"><span class=\"dots\"><i></i><i></i><i></i></span><span class=\"fname\">snippets</span></div><pre><span style=\"color: #F8F8F2\">{</span>\n<span style=\"color: #F8F8F2\">  </span><span style=\"color: #FF4689\">&quot;conv&quot;</span><span style=\"color: #F8F8F2\">: {</span>\n<span style=\"color: #F8F8F2\">    </span><span style=\"color: #FF4689\">&quot;prefix&quot;</span><span style=\"color: #F8F8F2\">: </span><span style=\"color: #E6DB74\">&quot;cc&quot;</span><span style=\"color: #F8F8F2\">,</span>\n<span style=\"color: #F8F8F2\">    </span><span style=\"color: #FF4689\">&quot;body&quot;</span><span style=\"color: #F8F8F2\">: </span><span style=\"color: #E6DB74\">&quot;${1|feat,fix,docs,chore,refactor,test,ci|}(${2:scope}): ${3:summary}&quot;</span>\n<span style=\"color: #F8F8F2\">  }</span>\n<span style=\"color: #F8F8F2\">}</span>\n</pre></div>\n<p class=\"keep-next\">پیام را انگلیسی نگه دار اگر تیم بین‌المللی است؛ برای مخزن فارسی آموزشی می‌توانی بدنه را فارسی و type را انگلیسی بگذاری — قرارداد را در CONTRIBUTING بنویس.</p>\n<div class=\"cols\">\n<div class=\"col\"><div class=\"col-title\">good</div>\n<p><code>fix(login): handle expired JWT on 401</code></p>\n<p>فعل امری، محدوده، نتیجه.</p>\n</div>\n<div class=\"col\"><div class=\"col-title\">bad</div>\n<p><code>fixed stuff</code> / <code>WIP</code> / <code>asdf</code> / <code>update files</code></p>\n</div>\n</div>\n<div class=\"callout callout-tip\"><div class=\"callout-title\">چند تغییر = چند کامیت</div>\n<p>اگر README و منطق auth را با هم عوض کردی، دو کامیت بساز (<code>add -p</code>). changelog دروغ نگوید.</p>\n</div>\n<div class=\"callout callout-interview\"><div class=\"callout-title\">سؤالات مصاحبه (با پاسخ)</div>\n<p><strong>Junior — type اجباری است؟</strong> برای Git نه؛ برای انسان و ربات در تیم‌های مدرن عملاً بله.</p>\n<p><strong>Senior — چرا ! و BREAKING هر دو؟</strong> <code>!</code> در عنوان برای انسان و parser سریع؛ footer برای توضیح مهاجرت. ابزارها هر دو را می‌فهمند.</p>\n</div>\n<h2><span class=\"hx\"><span class=\"hx-t\">✅ چک‌لیست فهم</span></span></h2>\n<div class=\"keep-block\"><div class=\"checklist\">\n<ul>\n<li>۱۰ کامیت آخرت Conventional است</li>\n<li>breaking را علامت می‌زنی</li>\n<li>WIP را قبل از ریویو می‌شکنی/squash می‌کنی</li>\n</ul>\n</div><p><strong>فصل بعد:</strong> بخش سوم — rebase تعاملی؛ جایی که Senior از Mid جدا می‌شود.</p></div>";
